{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 공영주차장마다 전기차 충전소를 꼭 설치해야 하는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "원문은 공영주차장마다 전기차 충전소를 반드시 설치해야 한다고 정하지 않는다. 환경친화적 자동차 전용주차구획은 주차면수 50면 이상인 공영주차장, 시·자치구 및 그 소속기관 청사 부설 주차장에 설치하되 총 주차대수의 5% 이상으로 한다고 규정한다(주차장:제25조의3제1항). 따라서 모든 공영주차장이 아니라 주차면수 50면 이상인 공영주차장 등 일정 대상에만 설치 의무가 있다.",
          "b_ids": "주차장:제25조의3제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
